export interface StoredObject {
  data: Uint8Array
  contentType: string
}

/**
 * Blob storage port. Object ids are generated by the server.
 * Implementations must not use a client-supplied filename as the path.
 */
export interface ObjectStorage {
  put(id: string, data: Uint8Array, contentType: string): Promise<void>
  get(id: string): Promise<StoredObject | null>
  delete(id: string): Promise<void>
}
